-- ============================================================
-- Физическая схема БД «онлайн-кинотеатр» (PostgreSQL 13+)
-- Соответствует концептуальной и логической схемам проекта.
--
-- Отличия в именах от логической схемы:
--   User -> users       (USER — зарезервированное слово PostgreSQL)
--   Cast -> movie_cast  (CAST — служебное слово SQL)
-- Остальные таблицы называются так же, в нижнем регистре.
--
-- Идентификаторы: GENERATED BY DEFAULT AS IDENTITY — значения
-- генерируются автоматически, но допускают явную загрузку id из CSV.
-- ============================================================

-- Для повторного запуска скрипта: удаляем таблицы (потомки раньше родителей)
DROP TABLE IF EXISTS
    review, watch, movie_cast, person, movie_genre, genre,
    movie, payment, subscription, users, plan, country
CASCADE;

-- ------------------------------------------------------------
-- Справочники
-- ------------------------------------------------------------

CREATE TABLE country (
    country_id  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    iso_code    CHAR(2)       NOT NULL,
    name        VARCHAR(100)  NOT NULL,
    CONSTRAINT pk_country          PRIMARY KEY (country_id),
    CONSTRAINT uq_country_iso_code UNIQUE (iso_code),
    CONSTRAINT ck_country_iso_code CHECK (iso_code = UPPER(iso_code))
);

CREATE TABLE plan (
    plan_id         INTEGER GENERATED BY DEFAULT AS IDENTITY,
    name            VARCHAR(50)   NOT NULL,
    price           NUMERIC(8,2)  NOT NULL,
    max_screens     SMALLINT      NOT NULL,
    max_resolution  VARCHAR(10)   NOT NULL,
    CONSTRAINT pk_plan                PRIMARY KEY (plan_id),
    CONSTRAINT uq_plan_name           UNIQUE (name),
    CONSTRAINT ck_plan_price          CHECK (price >= 0),
    CONSTRAINT ck_plan_max_screens    CHECK (max_screens BETWEEN 1 AND 10),
    CONSTRAINT ck_plan_max_resolution CHECK (max_resolution IN ('SD', 'HD', 'FHD', '4K'))
);

CREATE TABLE genre (
    genre_id  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    name      VARCHAR(50)  NOT NULL,
    CONSTRAINT pk_genre      PRIMARY KEY (genre_id),
    CONSTRAINT uq_genre_name UNIQUE (name)
);

CREATE TABLE person (
    person_id   INTEGER GENERATED BY DEFAULT AS IDENTITY,
    full_name   VARCHAR(150)  NOT NULL,
    birth_date  DATE,
    CONSTRAINT pk_person            PRIMARY KEY (person_id),
    CONSTRAINT ck_person_birth_date CHECK (birth_date >= '1850-01-01')
);

CREATE TABLE movie (
    movie_id      INTEGER GENERATED BY DEFAULT AS IDENTITY,
    title         VARCHAR(255)  NOT NULL,
    description   TEXT,
    release_year  SMALLINT      NOT NULL,
    duration_min  SMALLINT      NOT NULL,
    age_rating    VARCHAR(5)    NOT NULL,
    CONSTRAINT pk_movie              PRIMARY KEY (movie_id),
    CONSTRAINT ck_movie_release_year CHECK (release_year BETWEEN 1888 AND 2100),
    CONSTRAINT ck_movie_duration_min CHECK (duration_min > 0),
    CONSTRAINT ck_movie_age_rating   CHECK (age_rating IN ('0+', '6+', '12+', '16+', '18+'))
);

-- ------------------------------------------------------------
-- Пользователи, подписки, платежи
-- ------------------------------------------------------------

CREATE TABLE users (
    user_id        INTEGER GENERATED BY DEFAULT AS IDENTITY,
    country_id     INTEGER       NOT NULL,
    email          VARCHAR(255)  NOT NULL,
    password_hash  VARCHAR(255)  NOT NULL,
    display_name   VARCHAR(100)  NOT NULL,
    birth_date     DATE          NOT NULL,
    registered_at  TIMESTAMPTZ   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_users            PRIMARY KEY (user_id),
    CONSTRAINT uq_users_email      UNIQUE (email),
    CONSTRAINT fk_users_country    FOREIGN KEY (country_id)
        REFERENCES country (country_id) ON DELETE RESTRICT,
    CONSTRAINT ck_users_email      CHECK (email LIKE '%_@_%._%'),
    CONSTRAINT ck_users_birth_date CHECK (birth_date >= '1900-01-01')
);

CREATE TABLE subscription (
    subscription_id  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    user_id          INTEGER      NOT NULL,
    plan_id          INTEGER      NOT NULL,
    start_date       DATE         NOT NULL DEFAULT CURRENT_DATE,
    end_date         DATE         NOT NULL,
    status           VARCHAR(20)  NOT NULL DEFAULT 'active',
    CONSTRAINT pk_subscription        PRIMARY KEY (subscription_id),
    CONSTRAINT fk_subscription_user   FOREIGN KEY (user_id)
        REFERENCES users (user_id) ON DELETE RESTRICT,
    CONSTRAINT fk_subscription_plan   FOREIGN KEY (plan_id)
        REFERENCES plan (plan_id) ON DELETE RESTRICT,
    CONSTRAINT ck_subscription_dates  CHECK (end_date > start_date),
    CONSTRAINT ck_subscription_status CHECK (status IN ('active', 'expired', 'cancelled'))
);

CREATE TABLE payment (
    payment_id       INTEGER GENERATED BY DEFAULT AS IDENTITY,
    subscription_id  INTEGER        NOT NULL,
    amount           NUMERIC(10,2)  NOT NULL,
    paid_at          TIMESTAMPTZ    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    payment_method   VARCHAR(30)    NOT NULL,
    status           VARCHAR(20)    NOT NULL DEFAULT 'pending',
    CONSTRAINT pk_payment              PRIMARY KEY (payment_id),
    CONSTRAINT fk_payment_subscription FOREIGN KEY (subscription_id)
        REFERENCES subscription (subscription_id) ON DELETE RESTRICT,
    CONSTRAINT ck_payment_amount       CHECK (amount > 0),
    CONSTRAINT ck_payment_method       CHECK (payment_method IN ('card', 'paypal', 'sbp', 'apple_pay', 'google_pay')),
    CONSTRAINT ck_payment_status       CHECK (status IN ('pending', 'success', 'failed', 'refunded'))
);

-- ------------------------------------------------------------
-- Связи фильмов: жанры и участники (таблицы-связки)
-- ------------------------------------------------------------

CREATE TABLE movie_genre (
    movie_id  INTEGER  NOT NULL,
    genre_id  INTEGER  NOT NULL,
    CONSTRAINT pk_movie_genre       PRIMARY KEY (movie_id, genre_id),
    CONSTRAINT fk_movie_genre_movie FOREIGN KEY (movie_id)
        REFERENCES movie (movie_id) ON DELETE CASCADE,
    CONSTRAINT fk_movie_genre_genre FOREIGN KEY (genre_id)
        REFERENCES genre (genre_id) ON DELETE CASCADE
);

CREATE TABLE movie_cast (
    movie_id        INTEGER       NOT NULL,
    person_id       INTEGER       NOT NULL,
    role            VARCHAR(30)   NOT NULL,
    character_name  VARCHAR(150),
    CONSTRAINT pk_movie_cast        PRIMARY KEY (movie_id, person_id, role),
    CONSTRAINT fk_movie_cast_movie  FOREIGN KEY (movie_id)
        REFERENCES movie (movie_id) ON DELETE CASCADE,
    CONSTRAINT fk_movie_cast_person FOREIGN KEY (person_id)
        REFERENCES person (person_id) ON DELETE CASCADE,
    CONSTRAINT ck_movie_cast_role   CHECK (role IN ('actor', 'director', 'writer', 'producer', 'composer')),
    CONSTRAINT ck_movie_cast_character CHECK (character_name IS NULL OR role = 'actor')
);

-- ------------------------------------------------------------
-- Активность пользователей: просмотры и отзывы
-- ------------------------------------------------------------

CREATE TABLE watch (
    watch_id         INTEGER GENERATED BY DEFAULT AS IDENTITY,
    user_id          INTEGER      NOT NULL,
    movie_id         INTEGER      NOT NULL,
    started_at       TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    watched_seconds  INTEGER      NOT NULL DEFAULT 0,
    is_finished      BOOLEAN      NOT NULL DEFAULT FALSE,
    CONSTRAINT pk_watch                PRIMARY KEY (watch_id),
    CONSTRAINT fk_watch_user           FOREIGN KEY (user_id)
        REFERENCES users (user_id) ON DELETE CASCADE,
    CONSTRAINT fk_watch_movie          FOREIGN KEY (movie_id)
        REFERENCES movie (movie_id) ON DELETE CASCADE,
    CONSTRAINT ck_watch_watched_seconds CHECK (watched_seconds >= 0)
);

CREATE TABLE review (
    review_id    INTEGER GENERATED BY DEFAULT AS IDENTITY,
    user_id      INTEGER      NOT NULL,
    movie_id     INTEGER      NOT NULL,
    rating       SMALLINT     NOT NULL,
    review_text  TEXT,
    created_at   TIMESTAMPTZ  NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT pk_review        PRIMARY KEY (review_id),
    CONSTRAINT fk_review_user   FOREIGN KEY (user_id)
        REFERENCES users (user_id) ON DELETE CASCADE,
    CONSTRAINT fk_review_movie  FOREIGN KEY (movie_id)
        REFERENCES movie (movie_id) ON DELETE CASCADE,
    CONSTRAINT ck_review_rating CHECK (rating BETWEEN 1 AND 10)
);
